  KeyS: 'DOWN',
  KeyA: 'LEFT',
  KeyD: 'RIGHT'
};

document.addEventListener('keydown', (e) => {
  const dir = KEY_MAP[e.code];
  if (dir) {
    e.preventDefault();
    game.setDirection(dir);

    // If game is not yet running (ready overlay), start it.
    if (!game.isRunning) {
      game.begin();
      startGameLoop();
    }
  }
});

