content.text:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: #111;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  overflow: hidden;
  font-family: sans-serif;
}

canvas {
  background: #222;
}

.hidden {
  display: none !important;
}

#gameOver {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  color: #eee;
  z-index: 10;
}

#gameOver h1 {
  margin-bottom: 10px;
}

#gameOver button {
  margin-top: 15px;
  padding: 10px 25px;
  font-size: 16px;
  cursor: pointer;
  background: #444;
  color: #eee;
  border: 1px solid #888;
  border-radius: 4px;
}

#gameOver button:hover {
  background: #666;
}

/**
 * Snake Game — Minimal playable version (Ticket 1).
 *
 * Game logic is separated from rendering:
 *   - SnakeGame handles state, movement, collision, scoring.
 *   - Renderer handles drawing on the canvas.
 */

// ── Constants ──────────────────────────────────────────────

const DEFAULT_BOARD_SIZE = 20;
const TICK_INTERVAL = 150; // ms per tick

// ── Renderer ───────────────────────────────────────────────

const Renderer = {
  ctx: null,
  cellSize: 20,

  init(canvas) {
    this.ctx = canvas.getContext('2d');
  },

  setCellSize(size) {
    this.cellSize = size;
  },

  clear() {
    this.ctx.fillStyle = '#222';
    this.ctx.fillRect(0, 0, this.ctx.canvas.width, this.ctx.canvas.height);
  },

  drawGrid(size) {
    const ctx = this.ctx;
    const cellSize = this.cellSize;
    const boardPixel = size * cellSize;

    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;

    for (let i = 0; i <= size; i++) {
      // vertical
      ctx.beginPath();
      ctx.moveTo(i * cellSize, 0);
      ctx.lineTo(i * cellSize, boardPixel);
      ctx.stroke();

      // horizontal
      ctx.beginPath();
      ctx.moveTo(0, i * cellSize);
      ctx.lineTo(boardPixel, i * cellSize);
      ctx.stroke();
    }
  },

  drawSnake(snake) {
    const ctx = this.ctx;
    const cellSize = this.cellSize;

    ctx.fillStyle = '#0f0';

    for (const segment of snake) {
      ctx.fillRect(
        segment.x * cellSize + 1,
        segment.y * cellSize + 1,
        cellSize - 2,
        cellSize - 2
      );
    }
  },

  drawFood(food) {
    const ctx = this.ctx;
    const cellSize = this.cellSize;

    ctx.fillStyle = '#f00';
    ctx.fillRect(
      food.x * cellSize + 1,
      food.y * cellSize + 1,
      cellSize - 2,
      cellSize - 2
    );
  }
};

// ── Game State ─────────────────────────────────────────────

/**
 * @typedef {Object} Cell
 * @property {number} x
 * @property {number} y
 */

/**
 * @typedef {'UP'|'DOWN'|'LEFT'|'RIGHT'} Direction
 */

/**
 * @typedef {Object} GameOverState
 * @property {boolean} isGameOver
 * @property {number} score
 */

// ── SnakeGame ──────────────────────────────────────────────

class SnakeGame {
  /**
   * @param {number} boardSize - Number of cells per row/column.
   * @param {CanvasRenderingContext2D} ctx
   */
  constructor(boardSize, ctx) {
    this.boardSize = boardSize;
    this.ctx = ctx;

    /** @type {Cell[]} */
    this.snake = [];

    /** @type {Direction} */
    this.direction = 'RIGHT';

    /** @type {Direction} - Queued direction change, applied on next tick. */
    this.nextDirection = 'RIGHT';

    /** @type {Cell} */
    this.food = { x: 0, y: 0 };

    /** @type {number} */
    this.score = 0;

    /** @type {boolean} */
    this.isGameOver = false;

    /** @type {boolean} - Game is running (ready to receive input). */
    this.isRunning = false;
  }

  /** Initialize a fresh game at the given board size. */
  start() {
    this.boardSize = Math.min(this.boardSize, 99);
    const center = Math.floor(this.boardSize / 2);
    this.snake = [
      { x: center, y: center },
      { x: center - 1, y: center },
      { x: center - 2, y: center }
    ];
    this.direction = 'RIGHT';
    this.nextDirection = 'RIGHT';
    this.score = 0;
    this.isGameOver = false;
    this.isRunning = false;
    this.spawnFood();
  }

  /** Start the game — called after the "press any key" overlay. */
  begin() {
    this.isRunning = true;
  }

  /** Change the snake's direction. Ignores invalid reversals. */
  setDirection(newDir) {
    if (!this.isRunning || this.isGameOver) return;

    const opposites = { UP: 'DOWN', DOWN: 'UP', LEFT: 'RIGHT', RIGHT: 'LEFT' };
    if (opposites[newDir] === this.direction) return;

    this.nextDirection = newDir;
  }

  /** Advance the game by one tick. */
  tick() {
    if (!this.isRunning || this.isGameOver) return;

    // Apply queued direction.
    this.direction = this.nextDirection;

    // Compute new head position.
    const head = this.snake[0];
    let nx = head.x;
    let ny = head.y;

    switch (this.direction) {
      case 'UP':    ny--; break;
      case 'DOWN':  ny++; break;
      case 'LEFT':  nx--; break;
      case 'RIGHT': nx++; break;
    }

    // Check wall collision.
    if (nx < 0 || nx >= this.boardSize || ny < 0 || ny >= this.boardSize) {
      this.isGameOver = true;
      return;
    }

    // Check self collision.
    for (const seg of this.snake) {
      if (seg.x === nx && seg.y === ny) {
        this.isGameOver = true;
        return;
      }
    }

    // Move head.
    this.snake.unshift({ x: nx, y: ny });

    // Check food collision.
    if (nx === this.food.x && ny === this.food.y) {
      this.score++;
      this.spawnFood();
    } else {
      // Remove tail segment (no growth).
      this.snake.pop();
    }
  }

  /** Spawn food at a random empty cell. */
  spawnFood() {
    const occupied = new Set(this.snake.map(s => `${s.x},${s.y}`));
    let x, y;

    do {
      x = Math.floor(Math.random() * this.boardSize);
      y = Math.floor(Math.random() * this.boardSize);
    } while (occupied.has(`${x},${y}`));

    this.food = { x, y };
  }

  /** Get the pixel size of the canvas needed for the board. */
  get boardPixelSize() {
    return this.boardSize * Renderer.cellSize;
  }

  /** Render the current game state to the canvas. */
  render() {
    Renderer.clear();

    if (!this.isGameOver) {
      Renderer.drawGrid(this.boardSize);
      Renderer.drawFood(this.food);
      Renderer.drawSnake(this.snake);

      // Score display
      const ctx = this.ctx;
      ctx.fillStyle = '#fff';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(`Score: ${this.score}`, 10, 20);
    } else {
      // Show final score on canvas
      const ctx = this.ctx;
      ctx.fillStyle = '#fff';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(`Score: ${this.score}`, 10, 20);
    }

    // Show game over overlay if game is over
    if (this.isGameOver) {
      showGameOver();
    }
  }
}

// ── Setup & Game Loop ──────────────────────────────────────

const canvas = document.getElementById('gameCanvas');
const gameOverDiv = document.getElementById('gameOver');
const finalScoreEl = document.getElementById('finalScore');
const playAgainBtn = document.getElementById('playAgainBtn');

let game = null;

/**
 * Configure the canvas size to fit the board within the viewport.
 * Returns the cell size in pixels.
 */
function configureCanvas() {
  const cellSize = 20;
  const boardPixel = DEFAULT_BOARD_SIZE * cellSize;

  // Fit within viewport, leaving room for score display and padding.
  const maxWidth = Math.min(window.innerWidth - 40, window.innerHeight - 40);
  const maxHeight = maxWidth;

  if (boardPixel > maxWidth) {
    const scaledCell = Math.max(10, Math.floor(maxWidth / DEFAULT_BOARD_SIZE));
    Renderer.setCellSize(scaledCell);
    canvas.width = DEFAULT_BOARD_SIZE * scaledCell;
    canvas.height = DEFAULT_BOARD_SIZE * scaledCell;
  } else {
    canvas.width = boardPixel;
    canvas.height = boardPixel;
    Renderer.setCellSize(cellSize);
  }

  return Renderer.cellSize;
}

function showGameOver() {
  finalScoreEl.textContent = game.score;
  gameOverDiv.classList.remove('hidden');
}

function hideGameOver() {
  gameOverDiv.classList.add('hidden');
}

function startNewGame() {
  hideGameOver();
  Renderer.init(canvas);
  game = new SnakeGame(DEFAULT_BOARD_SIZE, canvas.getContext('2d'));
  game.start();
}

// Initial setup
const initialCellSize = configureCanvas();
startNewGame();

// Game loop using setInterval for consistent tick rate.
let tickInterval = null;

function startGameLoop() {
  if (tickInterval !== null) clearInterval(tickInterval);
  tickInterval = setInterval(() => {
    if (game) {
      game.tick();
      game.render();
      if (game.isGameOver) {
        showGameOver();
      }
    }
  }, TICK_INTERVAL);
}

