function startGameLoop() {
  if (tickInterval !== null) clearInterval(tickInterval);
  tickInterval = setInterval(() => {
    if (game) {
      game.tick();
      game.render();
      if (game.isGameOver) {
        showGameOver();
      }
    }
  }, TICK_INTERVAL);
