  // Center is (5,5). Go right 4 times
  for (let i = 0; i < 4; i++) { t5.setDirection('RIGHT'); t5.tick(); }
  // Head at (9,5), going right, length 7 (5 + 2 from score)
  t5.setDirection('DOWN'); t5.tick();
  t5.setDirection('LEFT'); t5.tick();
  t5.setDirection('UP'); t5.tick();
  // Head at (7,4), going UP
  t5.tick(); // head at (7,3), going UP
  // Self-collision? Body has (7,4),(8,4),(8,5),(9,5),...
  // Going UP from (7,3), next would be (7,2) - no collision yet
  // Let's try going RIGHT from (7,3): (8,3) - no collision
  t5.setDirection('RIGHT'); t5.tick();
  t5.setDirection('DOWN'); t5.tick();
  // Now going DOWN from (9,4), next: (9,5) - check if body has (9,5)
  return { gameOver: t5.isGameOver, snake: t5.snake.map(s => s.x+','+s.y), length: t5.snake.length };
})()
"

