content.text:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: #0a0a0a;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  overflow: hidden;
  font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
}

canvas {
  background: #111;
  display: block;
}

.hidden {
  display: none !important;
}

/* ── Menu Overlays (Start Menu & Game Over) ──────────────────── */

.overlay,
.menu-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 100;
}

.menu-overlay {
  background: rgba(0, 0, 0, 0.85);
}

.overlay {
  background: rgba(0, 0, 0, 0.6);
}

.menu-box,
.gameover-box {
  text-align: center;
  color: #eee;
}

.game-title {
  font-size: 52px;
  font-weight: 700;
  letter-spacing: 8px;
  color: #0ff;
  text-shadow: 0 0 10px #0ff, 0 0 20px #0ff;
  margin-bottom: 30px;
}

/* ── Menu Sections ───────────────────────────────────────────── */

.menu-section {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-bottom: 20px;
  font-size: 18px;
}

.menu-section label {
  color: #0ff;
  text-shadow: 0 0 4px #0ff;
  min-width: 80px;
  text-align: right;
}

.menu-section .input-hint {
  font-size: 13px;
  color: #666;
}

#boardSizeInput {
  width: 60px;
  padding: 6px 8px;
  font-size: 18px;
  text-align: center;
  background: #1a1a1a;
  color: #fff;
  border: 1px solid #0ff;
  border-radius: 4px;
  outline: none;
}

#boardSizeInput:focus {
  box-shadow: 0 0 6px #0ff;
}

/* ── High Score Display ──────────────────────────────────────── */

.high-score-label {
  color: #f0f;
  text-shadow: 0 0 4px #f0f;
}

.high-score-value {
  font-size: 28px;
  font-weight: 700;
  color: #f0f;
  text-shadow: 0 0 8px #f0f, 0 0 16px #f0f;
}

/* ── Buttons ─────────────────────────────────────────────────── */

.btn-primary {
  margin-top: 15px;
  padding: 12px 32px;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 2px;
  cursor: pointer;
  background: transparent;
  color: #0f0;
  border: 2px solid #0f0;
  border-radius: 4px;
  text-shadow: 0 0 4px #0f0;
  box-shadow: 0 0 8px rgba(0, 255, 0, 0.3);
  transition: background 0.2s, box-shadow 0.2s;
}

.btn-primary:hover {
  background: #0f0;
  color: #000;
  box-shadow: 0 0 20px rgba(0, 255, 0, 0.6);
}

/* ── Game Over specific ──────────────────────────────────────── */

#gameOver h1 {
  font-size: 42px;
  font-weight: 700;
  color: #f00;
  text-shadow: 0 0 10px #f00, 0 0 20px #f00;
  margin-bottom: 15px;
}

#gameOver p {
  font-size: 20px;
  margin-bottom: 8px;
}

#gameOver #finalScore {
  color: #0ff;
  text-shadow: 0 0 6px #0ff;
  font-weight: 700;
  font-size: 22px;
}

#gameOver #finalHighScore {
  color: #f0f;
  text-shadow: 0 0 6px #f0f;
  font-weight: 700;
  font-size: 22px;
}

#gameOver .btn-primary {
  margin-top: 20px;
}

/* ── Ready overlay text ──────────────────────────────────────── */

.overlay-text {
  font-size: 28px;
  font-weight: 600;
  color: #0ff;
  text-shadow: 0 0 8px #0ff, 0 0 16px #0ff;
  letter-spacing: 2px;
}

/* ── Game HUD ────────────────────────────────────────────────── */

.game-hud {
  position: absolute;
  top: 10px;
  left: 15px;
  z-index: 50;
  font-size: 22px;
  font-weight: 700;
  color: #0ff;
  text-shadow: 0 0 6px #0ff, 0 0 12px #0ff;
  letter-spacing: 1px;
}

/**
 * Snake Game — Ticket 2: Start menu + score system.
 *
 * Game logic is separated from rendering:
 *   - SnakeGame handles state, movement, collision, scoring.
 *   - Renderer handles drawing on the canvas.
 *
 * Session high-score tracking (no localStorage).
 */

// ── Constants ──────────────────────────────────────────────

const DEFAULT_BOARD_SIZE = 20;
const TICK_INTERVAL = 150; // ms per tick

// ── Session High Score ─────────────────────────────────────

let sessionHighScore = 0;

// ── Renderer ───────────────────────────────────────────────

const Renderer = {
  ctx: null,
  cellSize: 20,

  init(canvas) {
    this.ctx = canvas.getContext('2d');
  },

  setCellSize(size) {
    this.cellSize = size;
  },

  clear() {
    this.ctx.fillStyle = '#111';
    this.ctx.fillRect(0, 0, this.ctx.canvas.width, this.ctx.canvas.height);
  },

  drawGrid(size) {
    const ctx = this.ctx;
    const cellSize = this.cellSize;
    const boardPixel = size * cellSize;

    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 1;

    for (let i = 0; i <= size; i++) {
      // vertical
      ctx.beginPath();
      ctx.moveTo(i * cellSize, 0);
      ctx.lineTo(i * cellSize, boardPixel);
      ctx.stroke();

      // horizontal
      ctx.beginPath();
      ctx.moveTo(0, i * cellSize);
      ctx.lineTo(boardPixel, i * cellSize);
      ctx.stroke();
    }
  },

  drawSnake(snake) {
    const ctx = this.ctx;
    const cellSize = this.cellSize;

    ctx.fillStyle = '#0f0';
    ctx.shadowColor = '#0f0';
    ctx.shadowBlur = 6;

    for (const segment of snake) {
      ctx.fillRect(
        segment.x * cellSize + 1,
        segment.y * cellSize + 1,
        cellSize - 2,
        cellSize - 2
      );
    }

    ctx.shadowBlur = 0;
  },

  drawFood(food) {
    const ctx = this.ctx;
    const cellSize = this.cellSize;
    const padding = 1;

    // Draw a glowing square with a lighter center
    const fx = food.x * cellSize + padding;
    const fy = food.y * cellSize + padding;
    const fsize = cellSize - padding * 2;

    ctx.fillStyle = '#f00';
    ctx.shadowColor = '#f00';
    ctx.shadowBlur = 8;

    ctx.fillRect(fx, fy, fsize, fsize);

    // Inner highlight
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(fx + 2, fy + 2, fsize - 4, fsize - 4);

    ctx.shadowBlur = 0;
  }
};

// ── Game State ─────────────────────────────────────────────

/**
 * @typedef {Object} Cell
 * @property {number} x
 * @property {number} y
 */

/**
 * @typedef {'UP'|'DOWN'|'LEFT'|'RIGHT'} Direction
 */

// ── SnakeGame ──────────────────────────────────────────────

class SnakeGame {
  /**
   * @param {number} boardSize - Number of cells per row/column.
   * @param {CanvasRenderingContext2D} ctx
   */
  constructor(boardSize, ctx) {
    this.boardSize = boardSize;
    this.ctx = ctx;

    /** @type {Cell[]} */
    this.snake = [];

    /** @type {Direction} */
    this.direction = 'RIGHT';

    /** @type {Direction} - Queued direction change, applied on next tick. */
    this.nextDirection = 'RIGHT';

    /** @type {Cell} */
    this.food = { x: 0, y: 0 };

    /** @type {number} */
    this.score = 0;

    /** @type {boolean} */
    this.isGameOver = false;

    /** @type {boolean} - Game is running (ready to receive input). */
    this.isRunning = false;
  }

  /** Initialize a fresh game at the given board size. */
  start() {
    this.boardSize = Math.min(this.boardSize, 99);
    const center = Math.floor(this.boardSize / 2);
    this.snake = [
      { x: center, y: center },
      { x: center - 1, y: center },
      { x: center - 2, y: center }
    ];
    this.direction = 'RIGHT';
    this.nextDirection = 'RIGHT';
    this.score = 0;
    this.isGameOver = false;
    this.isRunning = false;
    this.spawnFood();
  }

  /** Start the game — called after the "press any key" overlay. */
  begin() {
    this.isRunning = true;
  }

  /** Change the snake's direction. Ignores invalid reversals. */
  setDirection(newDir) {
    if (!this.isRunning || this.isGameOver) return;

    const opposites = { UP: 'DOWN', DOWN: 'UP', LEFT: 'RIGHT', RIGHT: 'LEFT' };
    if (opposites[newDir] === this.direction) return;

    this.nextDirection = newDir;
  }

  /** Advance the game by one tick. */
  tick() {
    if (!this.isRunning || this.isGameOver) return;

    // Apply queued direction.
    this.direction = this.nextDirection;

    // Compute new head position.
    const head = this.snake[0];
    let nx = head.x;
    let ny = head.y;

    switch (this.direction) {
      case 'UP':    ny--; break;
      case 'DOWN':  ny++; break;
      case 'LEFT':  nx--; break;
      case 'RIGHT': nx++; break;
    }

    // Check wall collision.
    if (nx < 0 || nx >= this.boardSize || ny < 0 || ny >= this.boardSize) {
      this.isGameOver = true;
      return;
    }

    // Check self collision.
    for (const seg of this.snake) {
      if (seg.x === nx && seg.y === ny) {
        this.isGameOver = true;
        return;
      }
    }

    // Move head.
    this.snake.unshift({ x: nx, y: ny });

    // Check food collision.
    if (nx === this.food.x && ny === this.food.y) {
      this.score++;

      // Update session high-score.
      if (this.score > sessionHighScore) {
        sessionHighScore = this.score;
      }

      this.spawnFood();
    } else {
      // Remove tail segment (no growth).
      this.snake.pop();
    }
  }

  /** Spawn food at a random empty cell. */
  spawnFood() {
    const occupied = new Set(this.snake.map(s => `${s.x},${s.y}`));
    let x, y;

    do {
      x = Math.floor(Math.random() * this.boardSize);
      y = Math.floor(Math.random() * this.boardSize);
    } while (occupied.has(`${x},${y}`));

    this.food = { x, y };
  }

  /** Get the pixel size of the canvas needed for the board. */
  get boardPixelSize() {
    return this.boardSize * Renderer.cellSize;
  }

  /** Render the current game state to the canvas. */
  render() {
    Renderer.clear();

    if (!this.isGameOver) {
      Renderer.drawGrid(this.boardSize);
      Renderer.drawFood(this.food);
      Renderer.drawSnake(this.snake);
    }
  }
}

// ── DOM Elements ────────────────────────────────────────────

const canvas = document.getElementById('gameCanvas');
const startMenu = document.getElementById('startMenu');
const readyOverlay = document.getElementById('readyOverlay');
const boardSizeInput = document.getElementById('boardSizeInput');
const menuHighScoreEl = document.getElementById('menuHighScore');
const startGameBtn = document.getElementById('startGameBtn');
const gameHUD = document.getElementById('gameHUD');
const gameScoreEl = document.getElementById('gameScore');
const gameOverOverlay = document.getElementById('gameOver');
const finalScoreEl = document.getElementById('finalScore');
const finalHighScoreEl = document.getElementById('finalHighScore');
const playAgainBtn = document.getElementById('playAgainBtn');

/** Current SnakeGame instance. */
let game = null;

/** Interval id for the game loop. */
let tickInterval = null;

/** Current cell size in pixels. */
let cellSize = Renderer.cellSize;

// ── Canvas Configuration ────────────────────────────────────

/**
 * Configure the canvas size to fit the board within the viewport.
 * Returns the cell size in pixels.
 *
 * The board must never exceed the smaller viewport dimension minus UI chrome.
 * If individual cells would be smaller than ~12px, cap the size.
 */
function configureCanvas() {
  const boardPixel = game.boardSize * cellSize;

  // Fit within viewport, leaving room for score display and padding.
  const maxWidth = Math.min(window.innerWidth - 40, window.innerHeight - 40);
  const maxHeight = maxWidth;

  if (boardPixel > maxWidth) {
    // Scale down to fit viewport.
    const scaledCell = Math.max(12, Math.floor(maxWidth / game.boardSize));
    Renderer.setCellSize(scaledCell);
    canvas.width = game.boardSize * scaledCell;
    canvas.height = game.boardSize * scaledCell;
    cellSize = Renderer.cellSize;
  } else {
    canvas.width = boardPixel;
    canvas.height = boardPixel;
    Renderer.setCellSize(cellSize);
  }

  return Renderer.cellSize;
}

// ── Menu / Overlay Management ───────────────────────────────

/** Show the start menu, hide everything else. */
function showStartMenu() {
  startMenu.classList.remove('hidden');
  readyOverlay.classList.add('hidden');
  gameOverOverlay.classList.add('hidden');
  gameHUD.classList.add('hidden');
  canvas.classList.add('hidden');

  // Update high score display on start menu.
  menuHighScoreEl.textContent = sessionHighScore;
}

/** Hide the start menu, show the ready overlay. */
function showReadyOverlay() {
  startMenu.classList.add('hidden');
  readyOverlay.classList.remove('hidden');
  gameOverOverlay.classList.add('hidden');
  gameHUD.classList.add('hidden');
}

/** Hide ready overlay, show HUD and canvas, start the game loop. */
function startGameplay() {
  readyOverlay.classList.add('hidden');
  gameHUD.classList.remove('hidden');
  canvas.classList.remove('hidden');
  game.begin();
  startGameLoop();
}

/** Show the game-over overlay with scores. */
function showGameOver() {
  game.isGameOver = true;
  clearInterval(tickInterval);
  tickInterval = null;
  finalScoreEl.textContent = game.score;
  finalHighScoreEl.textContent = sessionHighScore;
  gameOverOverlay.classList.remove('hidden');
}

/** Hide game-over overlay, return to start menu. */
function hideGameOver() {
  gameOverOverlay.classList.add('hidden');
  gameHUD.classList.add('hidden');
  canvas.classList.add('hidden');
}

/** Update the real-time score display in the HUD. */
function updateScoreDisplay() {
  gameScoreEl.textContent = `Score: ${game.score}`;
}

// ── Game Lifecycle ──────────────────────────────────────────

/** Start a new game — initialize game state, configure canvas, render. */
function startNewGame() {
  const boardSize = Math.min(99, Math.max(10, parseInt(boardSizeInput.value) || DEFAULT_BOARD_SIZE));
  Renderer.init(canvas);

  game = new SnakeGame(boardSize, canvas.getContext('2d'));
  game.start();

  configureCanvas();
  game.render();
  updateScoreDisplay();
}

/** Start (or restart) the game loop. */
function startGameLoop() {
  if (tickInterval !== null) clearInterval(tickInterval);
  tickInterval = setInterval(() => {
    if (game) {
      game.tick();
      updateScoreDisplay();
      game.render();
      if (game.isGameOver) {
        showGameOver();
      }
    }
  }, TICK_INTERVAL);
}

// ── Start Game Button ───────────────────────────────────────

startGameBtn.addEventListener('click', () => {
  startNewGame();
  showReadyOverlay();
});

// ── Play Again Button ───────────────────────────────────────

playAgainBtn.addEventListener('click', () => {
  hideGameOver();
  showStartMenu();
});

// ── Input Handling ──────────────────────────────────────────

const KEY_MAP = {
  ArrowUp: 'UP',
  ArrowDown: 'DOWN',
  ArrowLeft: 'LEFT',
  ArrowRight: 'RIGHT',
  KeyW: 'UP',
  KeyS: 'DOWN',
  KeyA: 'LEFT',
  KeyD: 'RIGHT'
};

document.addEventListener('keydown', (e) => {
  const dir = KEY_MAP[e.code];

  // If we're on the ready overlay, dismiss it and begin the game on any key.
  if (!readyOverlay.classList.contains('hidden') && game && !game.isRunning) {
    e.preventDefault();
    startGameplay();
    // Apply the direction that triggered the start, if it's a valid direction.
    if (dir) {
      game.setDirection(dir);
    }
    return;
  }

  if (dir) {
