content.text:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: #0a0a0a;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  overflow: hidden;
  font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
  position: relative;
}

/* ── Scanline overlay ───────────────────────────────────── */

body::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.05) 2px,
    rgba(0, 0, 0, 0.05) 4px
  );
  z-index: 9999;
}

/* ── Neon corner accents for menus ───────────────────────── */

.menu-box::before,
.gameover-box::before {
  content: '';
  position: absolute;
  top: -2px;
  left: -2px;
  right: -2px;
  bottom: -2px;
  border: 2px solid #0ff;
  box-shadow: 0 0 8px #0ff, inset 0 0 8px rgba(0, 255, 255, 0.1);
  border-radius: 4px;
  pointer-events: none;
  opacity: 0.6;
}

.menu-box,
.gameover-box {
  position: relative;
}

canvas {
  background: #0d0d0d;
  display: block;
  border: 1px solid #1a1a2e;
  box-shadow: 0 0 20px rgba(0, 255, 255, 0.1);
}

.hidden {
  display: none !important;
}

/* ── Menu Overlays (Start Menu & Game Over) ──────────────────── */

.overlay,
.menu-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 100;
}

.menu-overlay {
  background: rgba(0, 0, 0, 0.85);
}

.overlay {
  background: rgba(0, 0, 0, 0.6);
}

.menu-box,
.gameover-box {
  text-align: center;
  color: #eee;
}

.game-title {
  font-size: 52px;
  font-weight: 700;
  letter-spacing: 8px;
  color: #0ff;
  text-shadow: 0 0 10px #0ff, 0 0 20px #0ff, 0 0 40px #0ff, 0 0 60px #0ff;
  margin-bottom: 30px;
  animation: titleGlow 2s ease-in-out infinite;
}

@keyframes titleGlow {
  0%, 100% {
    text-shadow: 0 0 10px #0ff, 0 0 20px #0ff, 0 0 40px #0ff, 0 0 60px #0ff;
  }
  50% {
